steps.body:
A type guard is a function that returns a `boolean` and declares its return type as `x is T`, where `x` is one of its parameters. When the guard returns `true`, TypeScript narrows the argument to `T` wherever you called it:

```typescript
function isNumber(x: unknown): x is number {
  return typeof x === "number";
}
const value: unknown = 21;
if (isNumber(value)) {
  console.log(value * 2); // 42
}
```

The body is the narrowing code you already know. The `x is T` part is a promise: the checker doesn't prove that the body checks what the signature claims, so a guard that returns `true` for the wrong value lies just like `!`. Check every field the type has.

Guards pay off with data from outside. Write `isUser(x: unknown): x is User` once, and every place that reads JSON can call it.

examples.code:
function isString(x: unknown): x is string {
  return typeof x === "string";
}

const cells: unknown[] = ["Ada", 36, "London", null, "1815"];
const words: string[] = [];
for (const cell of cells) {
  if (isString(cell)) {
    words.push(cell.toUpperCase());
    //         ^? const cell: string
  }
}
console.log(words.join(", "));

import { readFileSync } from "node:fs";

type User = { name: string; age: number };

function isUser(x: unknown): x is User {
  return (
    typeof x === "object" &&
    x !== null &&
    "name" in x &&
    typeof x.name === "string" &&
    "age" in x &&
    typeof x.age === "number"
  );
}

const data: unknown = JSON.parse(readFileSync(0, "utf8"));
const rows: unknown[] = Array.isArray(data) ? data : [];

for (const row of rows) {
  if (isUser(row)) {
    console.log(`${row.name} is ${row.age}`);
  } else {
    console.log(`skipped ${JSON.stringify(row)}`);
  }
}

type Cat = { name: string; lives: number };
type Dog = { name: string; tricks: string[] };

function isCat(pet: Cat | Dog): pet is Cat {
  return "lives" in pet;
}

const pets: (Cat | Dog)[] = [
  { name: "Tom", lives: 9 },
  { name: "Rex", tricks: ["sit", "roll over"] },
  { name: "Felix", lives: 7 },
];

for (const pet of pets) {
  if (isCat(pet)) {
    console.log(`${pet.name} has ${pet.lives} lives`);
  } else {
    console.log(`${pet.name} knows ${pet.tricks.join(" and ")}`);
  }
}

