import { readFileSync } from "node:fs";

export type Product = { sku: string; priceCents: number };

export function isProduct(x: unknown): x is Product {
  return (
    typeof x === "object" &&
    x !== null &&
    "sku" in x &&
    typeof x.sku === "string" &&
    "priceCents" in x &&
    typeof x.priceCents === "number"
  );
}

const data: unknown = JSON.parse(readFileSync(0, "utf8"));
const rows: unknown[] = Array.isArray(data) ? data : [];

let skipped = 0;
for (const row of rows) {
  if (isProduct(row)) {
    console.log(row.sku);
  } else {
    skipped++;
  }
}
console.log(`Skipped: ${skipped}`);

steps.body:
`filter` has a special form: when its callback is a type guard, it returns an array of the narrowed type. Since TypeScript 5.5 you often don't write that guard yourself. An arrow function like `(x) => x !== null` is *inferred* as a type predicate, so `filter` narrows the array:

```typescript
const scores = [90, null, 75];
const taken = scores.filter((s) => s !== null);
//    ^? const taken: number[]
console.log(taken.join(", ")); // 90, 75
```

The inference only happens when the check proves the type both ways: `true` means a `number`, and `false` means not a `number`. `filter(Boolean)` also drops `null` at run time, but `Boolean` is a plain function, not a guard, so the array keeps its old type. It drops `0` and `""` too.

`find` works the same way: give it a guard, and you get the narrowed type back, or `undefined` when nothing matches.

examples.code:
const names = ["Ada", null, "Grace", null, "Linus"];
//    ^? const names: (string | null)[]
const present = names.filter((n) => n !== null);
//    ^? const present: string[]
console.log(present.map((n) => n.toUpperCase()).join(", "));

const names = ["Ada", null, "Grace", null, "Linus"];
const present = names.filter(Boolean);
//    ^? const present: (string | null)[]
console.log(present.length);
console.log(present.join(", "));

examples.explanation:
At run time `filter(Boolean)` drops both `null`s, so 3 names are left. The type doesn't know that: `Boolean` isn't a type guard, so `present` is still `(string | null)[]`, and using an item as a string is a type error:

```typescript error
const names = ["Ada", null, "Grace"];
const present = names.filter(Boolean);
console.log(present.map((n) => n.toUpperCase()).join(", "));
```

TS18047 says `n` is possibly `null`. With numbers, `filter(Boolean)` has a second trap: it drops `0`, which is usually a real value.

examples.code:
type Cat = { name: string; lives: number };
type Dog = { name: string; tricks: string[] };

function isCat(pet: Cat | Dog): pet is Cat {
  return "lives" in pet;
}

const pets: (Cat | Dog)[] = [
  { name: "Rex", tricks: ["sit"] },
  { name: "Tom", lives: 9 },
  { name: "Felix", lives: 7 },
];

const firstCat = pets.find(isCat);
//    ^? const firstCat: Cat | undefined
console.log(firstCat ? `${firstCat.name} has ${firstCat.lives} lives` : "no cats");

const cats = pets.filter(isCat);
//    ^? const cats: Cat[]
console.log(`${cats.length} cats`);

