steps.body:
An assertion function checks a value and throws when the check fails, so it never returns `false`. Its return type says what is true once it returns: `asserts condition` for a condition, or `asserts x is T` for a type. Code after the call is narrowed, with no `if` around it:

```typescript
function assertIsNumber(x: unknown): asserts x is number {
  if (typeof x !== "number") {
    throw new Error(`expected a number, got ${typeof x}`);
  }
}
const value: unknown = 20;
assertIsNumber(value);
console.log(value + 1); // 21
```

Use a guard when bad data is normal and you want to skip it. Use an assertion when bad data means you should stop.

One rule trips people up. The checker only treats a call as an assertion when the function's type is written out, which every `function` declaration has. An arrow function stored in a `const` without a type annotation doesn't qualify, and calling it is error TS2775.

examples.code:
function assert(condition: boolean, message: string): asserts condition {
  if (!condition) {
    throw new Error(message);
  }
}

const stock = new Map<string, number>([
  ["mug", 4],
  ["plate", 0],
]);

function reserve(item: string, wanted: number): string {
  const left = stock.get(item);
  assert(left !== undefined, `unknown item: ${item}`);
  assert(left >= wanted, `only ${left} ${item} left`);
  //     ^? const left: number
  return `reserved ${wanted} ${item}`;
}

for (const item of ["mug", "plate", "cup"]) {
  try {
    console.log(reserve(item, 1));
  } catch (err) {
    console.log(err instanceof Error ? err.message : String(err));
  }
}

import { readFileSync } from "node:fs";

function assertIsString(x: unknown, label: string): asserts x is string {
  if (typeof x !== "string") {
    throw new Error(`${label} must be a string, got ${typeof x}`);
  }
}

const lines = readFileSync(0, "utf8").trim().split("\n");
for (const line of lines) {
  const value: unknown = JSON.parse(line);
  try {
    assertIsString(value, "name");
    console.log(`name: ${value.toUpperCase()}`);
  } catch (err) {
    console.log(err instanceof Error ? err.message : String(err));
  }
}

const assertIsString = (x: unknown): asserts x is string => {
  if (typeof x !== "string") {
    throw new Error("expected a string");
  }
};

const value: unknown = JSON.parse('"hello"');
assertIsString(value);
console.log(value.toUpperCase());

examples.explanation:
The arrow function has an `asserts` return type, but the `const` that holds it has no type annotation, so the call is TS2775. The checker then ignores the assertion, and `value` is still `unknown` on the next line, which is the second error. A `function` declaration fixes both:

```typescript
function assertIsString(x: unknown): asserts x is string {
  if (typeof x !== "string") {
    throw new Error("expected a string");
  }
}

const value: unknown = JSON.parse('"hello"');
assertIsString(value);
console.log(value.toUpperCase()); // HELLO
```

