practice.solution:
import { readFileSync } from "node:fs";

export type Order = { id: string; items: { sku: string; qty: number }[] };

function isItem(x: unknown): x is { sku: string; qty: number } {
  return (
    typeof x === "object" &&
    x !== null &&
    "sku" in x &&
    typeof x.sku === "string" &&
    "qty" in x &&
    typeof x.qty === "number"
  );
}

export function assertOrder(x: unknown): asserts x is Order {
  if (
    typeof x !== "object" ||
    x === null ||
    !("id" in x) ||
    typeof x.id !== "string"
  ) {
    throw new Error("missing id");
  }
  if (!("items" in x) || !Array.isArray(x.items)) {
    throw new Error("missing items");
  }
  if (!x.items.every(isItem)) {
    throw new Error("bad item");
  }
}

const lines = readFileSync(0, "utf8").trim().split("\n");
for (const line of lines) {
  const order: unknown = JSON.parse(line);
  try {
    assertOrder(order);
    const count = order.items.reduce((sum, item) => sum + item.qty, 0);
    console.log(`Order ${order.id}: ${count} items`);
  } catch (err) {
    const message = err instanceof Error ? err.message : String(err);
    console.log(`Invalid order: ${message}`);
  }
}
